<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\Database;
use Kulturhus\Verein\Finance;
$tests=0;
function check(bool $ok,string $label):void{global $tests;++$tests;if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){check(true,$label);return;}throw new RuntimeException('Not denied: '.$label);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Test A'),('b','Test B'); INSERT INTO actors(id,club_id,role) VALUES('f','a','treasurer'),('other','b','treasurer'),('m','a','members'),('u','a','member'),('ed','a','editor'),('ad','a','admin')");
$f=new Finance($db,'f');$other=new Finance($db,'other');
foreach(['m','u','ed','ad','unknown'] as $actor)denied(fn()=>(new Finance($db,$actor))->accounts(),"$actor has no implicit finance permission");
$db->exec("INSERT INTO actor_capabilities VALUES('m','local_finance')");check((new Finance($db,'m'))->canRead(),'explicit local finance grant');$db->exec("DELETE FROM actor_capabilities WHERE actor_id='m'");check(!(new Finance($db,'m'))->canRead(),'finance grant revocation is immediate');
check(Finance::cents('0,10')+Finance::cents('0,20')===30,'exact integer cents');
foreach(['1.000,50','1e3','1.001','-1','NaN','1000000000,01'] as $bad)denied(fn()=>Finance::cents($bad),'reject invalid amount '.$bad);
$bank=$f->createAccount('Testkonto','offline','10,00','2026-01-01');$cash=$f->createAccount('Testkasse','cash','10,00','2026-01-01');$foreign=$other->createAccount('Fremdes Konto','offline','0','2026-01-01');
denied(fn()=>$f->createAccount('Testkasse','cash','0','2026-01-01'),'duplicate account denied');
denied(fn()=>$f->createAccount('Future','cash','0','2099-01-01'),'future opening denied');
$data=['kind'=>'income','description'=>'Testbeleg','counterparty'=>'=FORMULA(test)','amount'=>'20,15','category'=>'general','document_date'=>'2026-08-01','due_date'=>'2026-08-15'];$key=bin2hex(random_bytes(16));$id=$f->createEntry($data,$key);check($f->createEntry($data,$key)===$id&&count($f->entries())===1,'duplicate submission creates exactly one entry');
check($f->overview('2026-08-01','2026-08-31')['income']===0,'open entry excluded from received income');
check($f->overview('2026-08-01','2026-08-31')['receivables']===2015,'open receivables exact');
denied(fn()=>$other->entry($id),'foreign entry read denied');denied(fn()=>$other->recordPayment($id,1,$foreign,'2026-08-10'),'foreign entry payment denied');denied(fn()=>$f->recordPayment($id,1,$foreign,'2026-08-10'),'foreign account payment denied');
denied(fn()=>$f->recordPayment($id,1,$bank,'2099-08-10'),'future payment denied');denied(fn()=>$f->recordPayment($id,1,$bank,'2025-12-31'),'pre-opening payment denied');
$f->recordPayment($id,1,$bank,'2026-08-10');check($f->overview('2026-08-01','2026-08-31')['income']===2015,'paid entry contributes once');
denied(fn()=>$f->recordPayment($id,1,$bank,'2026-08-10'),'duplicate payment denied');denied(fn()=>$f->cancel($id,2),'paid entry cannot be discarded');
check(array_column($f->accounts(),'balance_cents','id')[$bank]===3015,'account balance matches opening plus paid entry');
$expense=$f->createEntry(array_replace($data,['kind'=>'expense','amount'=>'11,00']),bin2hex(random_bytes(16)));denied(fn()=>$f->recordPayment($expense,1,$cash,'2026-08-10'),'negative cash denied');check($f->entry($expense)['status']==='open','failed cash write rolled back');
$in=$f->createEntry(array_replace($data,['amount'=>'2,00']),bin2hex(random_bytes(16)));$f->recordPayment($in,1,$cash,'2026-08-15');denied(fn()=>$f->recordPayment($expense,1,$cash,'2026-08-10'),'backdating cannot use later cash income');$f->recordPayment($expense,1,$cash,'2026-08-15');
check($f->overview('2026-08-01','2026-08-31')['expense']===1100,'expense chart independent of opening');
$don=$f->createEntry(array_replace($data,['kind'=>'donation','amount'=>'4,00']),bin2hex(random_bytes(16)));$f->recordPayment($don,1,$bank,'2026-08-16');$o=$f->overview('2026-08-01','2026-08-31');check($o['income']===2615&&$o['donations']===400,'money donation counted exactly once');
$goods=$f->createGoods(['donor'=>'Testspender','description'=>'Teststuhl','received_on'=>'2026-08-16','amount'=>'50,00','valuation'=>'Synthetischer Nachweis'],bin2hex(random_bytes(16)));check($f->overview('2026-08-01','2026-08-31')['income']===2615,'goods donation excluded from money flow');check(count($other->goods())===0,'goods tenant boundary');
$open=$f->createEntry($data,bin2hex(random_bytes(16)));$f->cancel($open,1);check($f->entry($open)['status']==='cancelled','discard preserves entry');check($f->overview('2026-08-01','2026-08-31')['receivables']===0,'discarded amount excluded from receivables');
denied(fn()=>$f->export(['from'=>'2026-09-01','to'=>'2026-08-01']),'invalid export range denied');check(str_contains($f->export(['kind'=>'donation']),"'=FORMULA(test)"),'finance export neutralizes spreadsheet formulas');
check(count($f->entries(['q'=>"' OR 1=1 --"]))===0,'finance search parameterized');$referenceEntry=$f->createEntry(array_replace($data,['description'=>'Beleg mit Lieferantennummer','notes'=>'Lieferanten-Rechnungsnummer: VR-2026-42']),bin2hex(random_bytes(16)));check(count($f->entries(['q'=>'VR-2026-42']))===1&&$f->entry($referenceEntry)['id']===$referenceEntry,'finance search includes stored supplier invoice number');check(count($other->entries())===0,'finance list tenant boundary');
$db->exec("UPDATE actors SET active=0 WHERE id='f'");denied(fn()=>$f->overview('2026-08-01','2026-08-31'),'finance actor deactivation immediate');$db->exec("UPDATE actors SET active=1 WHERE id='f'");
$book=$f->cashbook($cash,'2026-08-01','2026-08-31');check($book['opening']===1000&&$book['income']===200&&$book['expense']===1100&&$book['closing']===100,'cashbook reconciles opening and cash movements');
check(min(array_column($book['rows'],'balance'))>=0,'same-day cash ordering preserves covered running balances');
denied(fn()=>$other->cashbook($cash,'2026-08-01','2026-08-31'),'foreign cashbook denied');denied(fn()=>$f->cashbook($bank,'2026-08-01','2026-08-31'),'bank account cannot pretend to be cash');
denied(fn()=>$f->closeCashbook($cash,'2026-08-15','2,00'),'cash count discrepancy rejects closing');$f->closeCashbook($cash,'2026-08-15','1,00');
denied(fn()=>$f->closeCashbook($cash,'2026-08-15','1,00'),'duplicate closure denied');
$later=$f->createEntry(array_replace($data,['amount'=>'5,00']),bin2hex(random_bytes(16)));denied(fn()=>$f->recordPayment($later,1,$cash,'2026-08-15'),'closure blocks backdated new payment');
denied(fn()=>$f->reverse($in,2,'2026-08-15','Korrektur'),'closure blocks backdated reversal');denied(fn()=>$f->reverse($in,2,'2026-08-16','Korrektur'),'reversal cannot create negative cash');
$f->reverse($expense,2,'2026-08-16','Testkorrektur');check($f->entry($expense)['status']==='paid'&&$f->entry($expense)['reversed_on']==='2026-08-16','reversal retains original paid document');
check($f->cashbook($cash,'2026-08-16','2026-08-31')['opening']===100,'later report retains historical pre-reversal balance');check($f->cashbook($cash,'2026-08-16','2026-08-31')['closing']===1200,'separate opposite flow corrects cash balance');
denied(fn()=>$f->reverse($expense,2,'2026-08-17','Duplikat'),'duplicate reversal denied');
$f->reverse($don,2,'2026-09-01','Testkorrektur Folgemonat');check($f->overview('2026-08-01','2026-08-31')['donations']===400&&$f->overview('2026-09-01','2026-09-05')['donations']===-400,'reversal leaves prior month intact');
check(str_contains($f->exportCashbook($cash,'2026-08-01','2026-08-31'),'Korrektur: Testkorrektur'),'cash export includes correction chain');
denied(fn()=>$other->goodsEntry($goods),'foreign goods detail denied');
check($f->goodsEntry($goods)['origin']==='unknown','goods origin stored explicitly');
$before=count($f->entries());$db->exec("CREATE TRIGGER fail_finance_audit BEFORE INSERT ON audit_events FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test audit failure'; END");try{$f->createEntry($data,bin2hex(random_bytes(16)));throw new RuntimeException('Expected audit failure');}catch(PDOException){}check(count($f->entries())===$before,'finance mutation rolls back if audit fails');
echo "$tests finance checks passed\n";
